def load() -> pd.DataFrame:
    with open('data/wildfire/input/nifc_wildfires.csv', 'r') as f:
        lines = [f.readline() for _ in range(10)]
    return pd.DataFrame({'line': lines})

def process(nifc_data) -> pd.DataFrame:
    df = nifc_data.copy()
    df['Fires'] = df['Fires'].astype(int)
    return df[df['Year'] >= 2000][['Year', 'Fires']].rename(columns={'Fires': 'NIFC_Fires'})

def process(noaa_annual, nifc_annual):
    merged = noaa_annual.merge(nifc_annual, on='Year', how='inner')
    merged['diff'] = merged['NOAA_Fires'] - merged['NIFC_Fires']
    result = pd.DataFrame({
        'avg_diff': [round(merged['diff'].mean())],
        'years_compared': [len(merged)],
        'mean_noaa': [merged['NOAA_Fires'].mean()],
        'mean_nifc': [merged['NIFC_Fires'].mean()]
    })
    return result
